from typing import List

def minFlipsGridPalindrome(grid: List[List[int]]) -> int:
    n, m = len(grid), len(grid[0])
    ans = 0
    for i in range((n + 1) // 2):
        for j in range((m + 1) // 2):
            # 行回文 + 列回文 => 这至多 4 个对称位置必须相同（中线上的会重合）
            cells = {(i, j), (i, m - 1 - j), (n - 1 - i, j), (n - 1 - i, m - 1 - j)}
            ones = sum(grid[r][c] for r, c in cells)
            ans += min(ones, len(cells) - ones)   # 少数服从多数
    return ans
